import java.lang.reflect.Proxy;
import java.util.*;

public class Main {
    interface BeanNameAware { void setBeanName(String name); }
    interface InitializingBean { void afterPropertiesSet(); }
    interface DisposableBean { void destroy(); }
    interface Worker { String work(); }

    static final class Repository {
        String load() { return "data"; }
    }

    static final class WorkerBean implements Worker, BeanNameAware, InitializingBean, DisposableBean {
        private final List<String> events;
        private Repository repository;

        WorkerBean(List<String> events) {
            this.events = events;
            events.add("01 constructor target");
        }

        void setRepository(Repository repository) {
            this.repository = repository;
            events.add("02 populate dependency");
        }

        @Override
        public void setBeanName(String name) {
            events.add("03 aware beanName=" + name);
        }

        void postConstruct() {
            events.add("05 @PostConstruct");
        }

        @Override
        public void afterPropertiesSet() {
            events.add("06 afterPropertiesSet");
        }

        void customInit() {
            events.add("07 custom init");
        }

        @Override
        public String work() {
            events.add("11 target work uses " + repository.load());
            return "ok";
        }

        void preDestroy() {
            events.add("12 @PreDestroy");
        }

        @Override
        public void destroy() {
            events.add("13 DisposableBean.destroy");
        }

        void customDestroy() {
            events.add("14 custom destroy");
        }
    }

    interface BeanPostProcessor {
        Object before(Object bean, String name);
        Object after(Object bean, String name);
    }

    static final class ProxyCreatingBpp implements BeanPostProcessor {
        private final List<String> events;

        ProxyCreatingBpp(List<String> events) {
            this.events = events;
        }

        @Override
        public Object before(Object bean, String name) {
            events.add("04 BPP before init");
            return bean;
        }

        @Override
        public Object after(Object bean, String name) {
            events.add("08 BPP after init -> create proxy");
            Worker target = (Worker) bean;
            return Proxy.newProxyInstance(
                    Worker.class.getClassLoader(),
                    new Class<?>[]{Worker.class},
                    (proxy, method, args) -> {
                        events.add("10 proxy intercept " + method.getName());
                        return method.invoke(target, args);
                    }
            );
        }
    }

    static final class MiniContainer {
        private final List<String> events = new ArrayList<>();
        private final BeanPostProcessor bpp = new ProxyCreatingBpp(events);
        private WorkerBean rawTarget;
        private Worker exposedBean;

        Worker refresh() {
            // 1. 实例化
            rawTarget = new WorkerBean(events);
            // 2. 属性填充
            rawTarget.setRepository(new Repository());
            // 3. Aware 回调
            rawTarget.setBeanName("workerBean");
            // 4. BPP before
            Object current = bpp.before(rawTarget, "workerBean");
            WorkerBean target = (WorkerBean) current;
            // 5-7. 初始化回调
            target.postConstruct();
            target.afterPropertiesSet();
            target.customInit();
            // 8. BPP after (可能返回代理)
            exposedBean = (Worker) bpp.after(target, "workerBean");
            events.add("09 singleton published proxy=" + Proxy.isProxyClass(exposedBean.getClass()));
            return exposedBean;
        }

        void close() {
            // 销毁回调作用在 rawTarget（目标对象）而非 proxy
            rawTarget.preDestroy();
            rawTarget.destroy();
            rawTarget.customDestroy();
        }

        List<String> events() { return events; }
    }

    public static void main(String[] args) {
        MiniContainer container = new MiniContainer();
        Worker worker = container.refresh();
        System.out.println("business=" + worker.work());
        container.close();
        container.events().forEach(System.out::println);
        // 关键观察：
        // - BPP after 返回了代理，exposedBean 是代理而非 rawTarget
        // - work() 经过代理拦截（事件10），但 init 方法（05-07）不经过代理
        // - 销毁（12-14）作用在 rawTarget 上
    }
}
